#!/bin/bash
# 11-17 아침 읽기(읽기만) — 설치/cron·이미지·기동/재시작·11-16 22:00 KST(13:00Z) 이후 backend 로그 요약. 서버에 쓰지 않는다.
set -u
L=${1:-.}
ssh -o BatchMode=yes cat-prod 'echo "조회 $(date "+%F %T %Z")"; echo "crontab $(crontab -l | sha256sum | cut -d" " -f1)"; echo "INSTALLED_SHA $(cat ~/ops-scripts/INSTALLED_SHA)"; cd ~/crypto_trader/AutoTrader && echo "HEAD $(git rev-parse HEAD)"; for s in backend frontend db; do c=$(docker compose -f docker-compose.prod.yml ps -q $s); docker inspect --format "$s Image={{.Image}} StartedAt={{.State.StartedAt}} RestartCount={{.RestartCount}} Status={{.State.Status}}" $c; done; ls -l --time-style=full-iso ~/daily-check | tail -3' </dev/null > $L/state.txt 2>&1
ssh -o BatchMode=yes cat-prod 'cd ~/crypto_trader/AutoTrader && c=$(docker compose -f docker-compose.prod.yml ps -q backend); z() { docker logs --since 2026-11-16T13:00:00Z $c 2>&1; }; echo "로그 줄 $(z | wc -l)"; z | grep -oE "^[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}" | sed -n "1p;\$p"; echo "ERROR $(z | grep -c " ERROR ")"; z | grep " ERROR " | grep -oE " ERROR +[^ ]+ - .{0,60}" | sed -E "s/[0-9]+/N/g" | sort | uniq -c | sort -rn | head -15; echo "Hikari 누수 $(z | grep -c "Connection leak detection") · 획득 실패 $(z | grep -c "Connection is not available")"; echo "OutOfMemory $(z | grep -c OutOfMemory) · Started $(z | grep -c "Started CryptoAutoTraderApplication")"; echo "캔들 판정 불가 $(z | grep -c "판정 불가")"; echo "N17 $(z | grep -c "REST 강제 갱신 시세가 가격이 아님") · N19 $(z | grep -c "REST 폴백 시세 항목 건너뜀") · N20 $(z | grep -cF "[시세 보강] 시세 항목 건너뜀") · N20회차오류 $(z | grep -cF "[시세 보강] 회차 오류")"; echo "뉴스 미완료 $(z | grep -c "수집 미완료")"; z | grep "수집 미완료" | grep -oE "sourceId=[a-z_]+ 결과=[A-Z_]+ 종류=[A-Za-z_0-9]+" | sort | uniq -c' </dev/null > $L/logs-since-2200.txt 2>&1
grep -cE '[0-9]{8,10}:[A-Za-z0-9_-]{30,}' $L/state.txt $L/logs-since-2200.txt > $L/token-check.txt
